-- Import structuré des deux catalogues transmis le 20 août 2026.
-- 124 formations du catalogue complet + 20 formations médicales détaillées.

ON CONFLICT (code) DO UPDATE SET
  title = CASE WHEN courses.published THEN courses.title ELSE EXCLUDED.title END,
  category = EXCLUDED.category,
  axis = EXCLUDED.axis,
  audience = EXCLUDED.audience,
  source_catalog = EXCLUDED.source_catalog,
  description = COALESCE(NULLIF(courses.description, ''), EXCLUDED.description),
  need = COALESCE(EXCLUDED.need, courses.need),
  objective = COALESCE(NULLIF(courses.objective, ''), EXCLUDED.objective),
  methods = COALESCE(EXCLUDED.methods, courses.methods),
  benefit = COALESCE(EXCLUDED.benefit, courses.benefit),
  program = CASE WHEN jsonb_array_length(EXCLUDED.program) > 0 THEN EXCLUDED.program ELSE courses.program END,
  duration_minutes = CASE WHEN courses.published THEN courses.duration_minutes ELSE EXCLUDED.duration_minutes END,
  lifecycle_status = CASE WHEN courses.published THEN 'published' ELSE 'catalog' END,
  updated_at = NOW();
